<?php

declare(strict_types=1);
namespace App\Tools\DifalIcmsCalculator\Domain\Services;
use App\Core\Dates\ReferenceDate; use App\Core\Math\{IntegerRounding,RoundingMode}; use App\Core\Money\{Money,Percentage}; use App\Core\Normative\{NormativeRuleResolver,NormativeRuleSnapshot}; use App\Core\Tools\Calculation\Data\{CalculationMemory,CalculationMemoryStep}; use App\Tools\DifalIcmsCalculator\Domain\Data\{DifalInput,DifalResult}; use App\Tools\DifalIcmsCalculator\Domain\Rules\{IcmsInterstateRule,RuleCatalog}; use InvalidArgumentException;
final class DifalCalculator { public function calculate(DifalInput $i): DifalResult { if($i->originUf===$i->destinationUf) throw new InvalidArgumentException('DIFAL exige UFs distintas.'); if($i->internalRate->millionthsOfPercent()<0||$i->internalRate->millionthsOfPercent()>=100_000_000) throw new InvalidArgumentException('Alíquota interna inválida.'); $date=ReferenceDate::fromString($i->competence->toString().'-01'); $rule=(new NormativeRuleResolver)->resolveCurrent(RuleCatalog::interstate(),'difal.icms.interstate',$date); assert($rule instanceof IcmsInterstateRule); $inter=$i->interstateOverride??Percentage::fromString($rule->rateFor($i->originUf,$i->destinationUf,$i->imported)); if($i->internalRate->millionthsOfPercent()<$inter->millionthsOfPercent()) throw new InvalidArgumentException('A alíquota interna informada não pode ser inferior à interestadual para este cálculo de DIFAL.'); $origin=$i->base->percentage($inter); $destBase=$i->base; if($i->method==='double_base'){ $net=$i->base->subtract($origin); $den=100_000_000-$i->internalRate->millionthsOfPercent(); $destBase=Money::fromMinor(IntegerRounding::divide($net->minorAmount()*100_000_000,$den,RoundingMode::HalfUp)); } elseif($i->method!=='single_base') throw new InvalidArgumentException('Método de base inválido.'); $destIcms=$destBase->percentage($i->internalRate); $difal=$i->method==='double_base'?$destIcms->subtract($origin):$i->base->percentage($i->internalRate)->subtract($i->base->percentage($inter)); $fcp=$destBase->percentage($i->fcpRate); $total=$difal->add($fcp); $memory=new CalculationMemory('1.0.0',[new CalculationMemoryStep('interstate','Alíquota interestadual','Resoluções do Senado ou percentual informado',['origin'=>$i->originUf,'destination'=>$i->destinationUf,'imported'=>$i->imported],$inter->toDecimalString().'%'),new CalculationMemoryStep('base','Base no destino',$i->method==='double_base'?'(base - ICMS origem) ÷ (1 - alíquota interna)':'base informada',['base_minor'=>$i->base->minorAmount(),'method'=>$i->method],$destBase->minorAmount(),'HalfUp em centavos.'),new CalculationMemoryStep('difal','DIFAL',$i->method==='double_base'?'ICMS destino - ICMS origem':'base × (alíquota interna - interestadual)',['internal'=>$i->internalRate->toDecimalString(),'interstate'=>$inter->toDecimalString()],$difal->minorAmount(),'HalfUp em centavos.'),new CalculationMemoryStep('fcp','FCP','base destino × alíquota FCP informada',['fcp_rate'=>$i->fcpRate->toDecimalString()],$fcp->minorAmount(),'Somente quando aplicável à mercadoria/operação.')],[NormativeRuleSnapshot::fromRule($rule,$date)],['A alíquota interna e o FCP dependem da legislação da UF de destino, mercadoria/serviço, NCM, benefícios e enquadramento; devem ser confirmados pelo usuário.','A alíquota interestadual de 4% só se aplica às hipóteses da Resolução do Senado nº 13/2012; marque importado apenas quando a operação estiver abrangida.','O método de base dupla é uma simulação parametrizada e só deve ser usado quando a legislação aplicável ao caso exigir essa sistemática.','A responsabilidade pelo recolhimento difere conforme o destinatário seja contribuinte ou não contribuinte do ICMS.','A ferramenta não substitui consulta à legislação estadual, Portal Nacional do DIFAL, GNRE/DARE ou validação fiscal da operação.'],true); return new DifalResult($origin,$destBase,$destIcms,$difal,$fcp,$total,$inter,$memory); } }
